source.response_shape:
{
  "data_as_of": "YYYY-MM-DD",
  "portfolios": {
    "UST|ST|INT|LTC|LTA": {
      "code": "string",
      "name": "string",
      "characteristics": { /* ETF-level metrics */ },
      "holdings": [ /* per-holding weight/return data */ ],
      "allocation": { /* asset class breakdown */ }
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "as_of_date": "YYYY-MM-DD",
  "data_as_of": "YYYY-MM-DD",  /* backward-compat alias */
  "note": "string",
  "portfolios": {
    "UST|ST|INT|LTC|LTA": {
      /* hierarchical: asset_class > sub_asset_class > ETF ticker */
      /* per-holding: weight, return, allocation_effect, selection_effect */
      /* periods: QTD, YTD (1Y and SI not yet generated — see data_quality_notes) */
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "portfolios": {
    "UST|ST|INT|LTC|LTA": {
      /* hierarchical allocation: asset_class > sub_asset_class */
      /* per-node: actual_weight, benchmark_weight, active_weight */
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "etfs": {
    "BIL|VGSH|AGG|IVV|ACWI": {
      "name": "string",
      "asset_class": "string",
      "1D": float, "WTD": float, "MTD": float, "1M": float,
      "QTD": float, "1Q": float, "YTD": float, "1Y": float,
      "since_inception": float
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "summary": { /* per-model: R2, alpha, conviction, consensus */ },
  "factorTiltsByWindow": {
    "1M|2M|3M|6M|1Y": {
      /* per-model, per-factor: tilt magnitude and direction */
    }
  },
  "aggregateTilts": { /* AUM-weighted AGG across all models */ },
  "models": ["UST", "ST", "INT", "LTC", "LTA", "AGG"],
  "windows": ["1M", "2M", "3M", "6M", "1Y"],
  "factors": ["Equity vs FI", "Growth vs Value", "US vs Foreign",
              "Large vs Small", "Agg vs Short", "HY vs Agg"]
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "factorSpreads": {
    /* per-factor: array of {date, value} rolling cumulative spread */
  },
  "factors": ["Equity vs FI", "Growth vs Value", "US vs Foreign",
              "Large vs Small", "Agg vs Short", "HY vs Agg"]
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "timeSeries": {
    /* market factor spreads: per-factor historical time series */
  },
  "modelTiltTimeSeries": {
    /* per-model, per-window rolling regression history */
  },
  "factors": [ /* same 6 factors */ ],
  "models": [ /* UST, ST, INT, LTC, LTA, AGG */ ],
  "windows": ["1M", "2M", "3M", "6M", "1Y", "2Y"]
}

{
  "data_as_of": "YYYY-MM-DD",
  "summary": [
    {
      "index": "string",
      "fwd_pe": float, "trailing_pe": float, "p_fcf": float,
      "ev_sales": float, "p_b": float, "p_sales": float, "div_yield": float,
      /* percentile rank (0-100) for each metric vs full history */
      "fwd_pe_pct": float, "trailing_pe_pct": float, /* etc. */
    }
    /* one row per equity index (~40+ entries) */
  ],
  "ranges": {
    "S&P 500|...": {
      /* p10, p25, p50, p75, p90 thresholds per metric */
      /* only 8 of 40+ indices have range data — see data_quality_notes */
    }
  },
  "time_series": {
    "S&P 500|...": {
      "fwd_pe|trailing_pe|...": {
        "values": [{"date": "YYYY-MM-DD", "value": float}],
        "percentile_bands": {"p10": float, "p25": float, "p50": float, "p75": float, "p90": float}
      }
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "data_source": {
    "erp": "string (source description)",
    "credit_spreads": "string (FRED series IDs)"
  },
  "note": "string (sampling methodology: monthly ERP, NO 6-month sampling; daily credit spreads)",
  "erp": {
    "data": [{"date": "YYYY-MM-DD", "value": float}],
    "thresholds": {"p10": float, "p25": float, "p50": float, "p75": float, "p90": float}
  },
  "credit": {
    "ig": {
      "data": [{"date": "YYYY-MM-DD", "value": float}],
      "thresholds": { /* percentile bands */ }
    },
    "hy": {
      "data": [{"date": "YYYY-MM-DD", "value": float}],
      "thresholds": { /* percentile bands */ }
    }
  }
}

{
  "generated_at": "ISO-8601 timestamp",
  "data_as_of": "YYYY-MM-DD",
  "groups": [
    {
      "name": "string (group category)",
      "indicators": [
        {
          "name": "string",
          "bloomberg_ticker": "string",
          "latest_value": float,
          "percentile": float,    /* 0-100 percentile vs history */
          "values": [             /* trailing 12 months for Value mode */
            {"date": "YYYY-MM-DD", "value": float}
          ],
          "thresholds": {"p10": float, "p90": float}  /* for Position mode */
        }
      ]
    }
  ]
}

{
  /* subset of macro_data.json — VIX indicator extracted for portal convenience */
  "data_as_of": "YYYY-MM-DD",
  "vix": {
    "latest": float,
    "percentile": float,
    "values": [{"date": "YYYY-MM-DD", "value": float}]
  }
}

{
  "indicator": "string (display name)",
  "as_of": "YYYY-MM-DD",
  "data": [{"date": "YYYY-MM-DD", "value": float}],
  "stats": {
    "min": float, "max": float, "mean": float,
    "latest": float, "count": int
  }
}

{
  "as_of": "YYYY-MM-DD",
  "vix": {
    "current": float,
    "percentile": float,       /* vs last 252 trading days */
    "status": "string",        /* e.g., "elevated", "normal", "low" */
    "history": [{"date": "YYYY-MM-DD", "value": float}]  /* last 252 days */
  },
  "move": {
    "current": null,           /* CURRENTLY NULL — data source incomplete */
    "percentile": null,
    "status": null,
    "history": []
  }
}

{
  "data_as_of": "YYYY-MM-DD",
  "metadata": {
    "generated_at": "ISO-8601 timestamp",
    "ticker_count": int,       /* ~55 */
    "periods_available": ["1M", "3M", "6M", "1Y", "2Y"]
  },
  "tickers": ["string", ...],  /* ordered list of index names */
  "correlations": {
    "1M|3M|6M|1Y|2Y": {
      "matrix": [[float, ...]],  /* lower-triangular NxN matrix; null above diagonal */
      "data_points": int         /* number of monthly observations used */
    }
  }
}
